def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_d = sum(1 for a in opp if a == 'D')
    last_me, last_opp = history[-1]

    # Opening: cooperate, but retaliate against immediate defection
    if n < 3:
        if last_opp == 'D':
            return 'D'
        return 'C'

    recent_len = 8 if n >= 8 else n
    recent_opp = opp[-recent_len:]
    recent_me = me[-recent_len:]
    recent_opp_d = sum(1 for a in recent_opp if a == 'D')
    recent_me_d = sum(1 for a in recent_me if a == 'D')

    # Compute consecutive opponent defections at end
    cons_opp_d = 0
    for a in reversed(opp):
        if a == 'D':
            cons_opp_d += 1
        else:
            break

    # Cons opponent cooperations at end
    cons_opp_c = 0
    for a in reversed(opp):
        if a == 'C':
            cons_opp_c += 1
        else:
            break

    # Detect consistent defector
    if opp_d * 100 >= n * 80:
        return 'D'

    # Cooperative opponent: exploit gently, but keep relationship
    if opp_d == 0:
        if n > 20 and rng.random() < 0.12:
            return 'D'
        return 'C'

    # If recent opponent mostly defecting, retaliate strongly
    if recent_opp_d * 3 >= recent_len * 2:
        if last_opp == 'C' and rng.random() < 0.2:
            return 'C'
        return 'D'

    # Detect mutual defection loops: break out occasionally
    if cons_opp_d >= 2 and last_me == 'D' and recent_me_d >= 2:
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    # If opponent just defected after cooperation, retaliate
    if last_opp == 'D':
        if cons_opp_d == 1 and opp_d * 3 < n:
            # Single defection after cooperation: punish once
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated last
    if cons_opp_c >= 3:
        # Sustained cooperation; cooperate but occasionally probe
        if n > 15 and rng.random() < 0.08:
            return 'D'
        return 'C'

    # Moderate opponent: generous tit-for-tat
    if opp_d * 100 < n * 40:
        return 'C'
    if last_opp == 'C':
        if n > 25 and rng.random() < 0.1:
            return 'D'
        return 'C'
    return 'D'
